package com.muthumol.player.dummy;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.media3.common.*;import java.util.*;import org.json.*;
/** TV-only actions share the live player. Subtitle controls are owned by PlayerActivity. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class TvPlayerTools {
 Button nextUp,skipButton;Movie nextUpMovie;boolean nextDismissed;List<SkipSegments.Segment> skipSegments=Collections.emptyList();SkipSegments.Segment activeSkip;
 final PlayerActivity a;final TvLibrary library;long undo=-1,undoUntil;boolean locked,undoing;long held;Dialog nextDialog;int nextSeconds;final Handler ui=new Handler(Looper.getMainLooper());
 TvPlayerTools(PlayerActivity activity){a=activity;library=new TvLibrary(a);library.remember(a.movie());}
 void choose(String title,String[] entries,java.util.function.IntConsumer action){Ui.menu(a,title,entries,action);}
 void menu(){if(a.player==null)return;choose("Playback options",new String[]{"Audio & clear dialogue","Playback speed · "+a.player.getPlaybackParameters().speed+"×","Episodes / next / previous","Go to time","Undo last seek","Chapters","Frame step (paused)","Picture shape","Remote lock · hold OK to unlock","Watch later · "+library.marked(a.movie(),"later"),"Mark watched / unwatched","Playback details","Open stream in another player","Phone gestures","Video decoder","Background audio","Telegram stream quality"},n->{switch(n){case 0:audioMenu();break;case 1:speed();break;case 2:episodes();break;case 3:time();break;case 4:undo();break;case 5:chapters();break;case 6:frame();break;case 7:a.aspectRatio();break;case 8:locked=true;a.view.hideController();toast("Locked. Hold OK for 2 seconds to unlock.");break;case 9:library.toggle(a.movie(),"later");break;case 10:library.toggle(a.movie(),"watched");StorageReview.cleanup(a);break;case 11:details();break;case 12:StreamHandoff.open(a);break;case 13:PlayerGestures.settings(a);break;case 14:choose("Video decoder",new String[]{"Automatic hardware / software fallback","Prefer software"},x->{a.prefs.edit().putBoolean("tvPreferSoftware",x==1).apply();restart();});break;case 15:BackgroundAudio.start(a);break;case 16:StreamVariants.show(a);break;}});}
 void audioMenu(){choose("Sound",new String[]{"Audio tracks","Sound profile · "+new String[]{"Original","Clear Dialogue","Clear Dialogue Strong","Night"}[a.prefs.getInt("tvAudioMode",1)],"Volume boost · "+a.boost+"%","Output · "+(a.stereo?"TV speakers / stereo":"Multichannel PCM"),"Audio delay · "+a.prefs.getLong("audioDelayMs",0)+" ms","Volume levelling · "+a.prefs.getBoolean("tvNormalize",true)},n->{if(n==0)a.audioMenu();if(n==1)choose("Sound profile",new String[]{"Original","Clear Dialogue","Clear Dialogue Strong","Night"},x->{a.prefs.edit().putInt("tvAudioMode",x).apply();restart();});if(n==2)choose("Volume boost",new String[]{"100%","125%","150%","175%","200%","250%","300%"},x->{a.boost=new int[]{100,125,150,175,200,250,300}[x];a.prefs.edit().putInt("boost",a.boost).apply();a.applyBoost(0);});if(n==4){EditText input=Ui.input(a,"Audio delay −5000 to +5000 milliseconds",false);input.setInputType(4098);input.setText(""+a.prefs.getLong("audioDelayMs",0));Ui.dialog(a).setTitle("Audio lip sync").setView(input).setPositiveButton("Apply",(d,w)->{try{long delay=Long.parseLong(input.getText().toString());if(Math.abs(delay)>5000)throw new IllegalArgumentException();a.prefs.edit().putLong("audioDelayMs",delay).apply();}catch(Exception e){toast("Use −5000 to +5000 ms");}}).setNegativeButton("Cancel",null).show();}if(n==5){boolean enabled=!a.prefs.getBoolean("tvNormalize",true);a.prefs.edit().putBoolean("tvNormalize",enabled).apply();a.voiceProcessor.normalize=enabled;}if(n==3)choose("Audio output",new String[]{"TV speakers / stereo","Multichannel PCM · receiver must support it"},x->{a.stereo=x==0;a.prefs.edit().putBoolean("stereo",a.stereo).apply();restart();});});}
 void restart(){if(a.player==null)return;a.resumePosition=a.player.getCurrentPosition();a.resumePlaying=a.player.getPlayWhenReady();a.savePosition();a.release();a.start();}
 void speed(){String[] names={"0.25×","0.5×","0.75×","1×","1.25×","1.5×","1.75×","2×","3×","4×","Fine adjustment"};choose("Playback speed",names,n->{if(n==10){EditText input=Ui.input(a,"Speed 0.25–4.0",false);input.setInputType(8194);input.setText(""+a.player.getPlaybackParameters().speed);Ui.dialog(a).setTitle("Playback speed").setView(input).setPositiveButton("Apply",(d,w)->{try{setSpeed(Float.parseFloat(input.getText().toString()));}catch(Exception e){toast("Enter a speed from 0.25 to 4");}}).setNegativeButton("Cancel",null).show();}else setSpeed(new float[]{.25f,.5f,.75f,1,1.25f,1.5f,1.75f,2,3,4}[n]);});}
 void setSpeed(float speed){if(!Float.isFinite(speed)||speed<.25f||speed>4){toast("Use 0.25–4.0");return;}a.player.setPlaybackSpeed(speed);a.prefs.edit().putFloat("tvSpeed",speed).apply();}
 void time(){EditText input=Ui.input(a,"HH:MM:SS or MM:SS",false);input.setText(CinemaInfo.time(a.player.getCurrentPosition()));Ui.dialog(a).setTitle("Go to time").setView(input).setPositiveButton("Go",(d,w)->{try{long t=parseTime(input.getText().toString());long duration=a.player.getDuration();a.player.seekTo(duration>0?Math.min(duration,t):t);}catch(Exception e){toast("Enter a valid time");}}).setNegativeButton("Cancel",null).show();}
 static long parseTime(String text){String[] bits=text.trim().split(":");if(bits.length<1||bits.length>3)throw new IllegalArgumentException();long s=0;for(String bit:bits){long n=Long.parseLong(bit);if(n<0||n>9999)throw new IllegalArgumentException();s=Math.addExact(Math.multiplyExact(s,60),n);}return Math.multiplyExact(s,1000);}
 void seeked(long from,long to,int reason){if(reason!=Player.DISCONTINUITY_REASON_SEEK)return;if(!undoing&&Math.abs(to-from)>=60000){undo=from;undoUntil=SystemClock.elapsedRealtime()+15000;}undoing=false;}
 void undo(){if(undo<0||SystemClock.elapsedRealtime()>undoUntil){toast("No recent large seek to undo");return;}undoing=true;a.player.seekTo(undo);undo=-1;}
 void neighbour(int direction){Movie next=TvLibrary.neighbour(a.items,a.movie(),direction);if(next==null)toast("No "+(direction<0?"previous":"next")+" episode found");else WatchSync.get(a).beforePlay(()->play(next));}
 void episodes(){List<Movie> movies=TvLibrary.episodes(a.items,a.movie());if(movies.isEmpty()){toast("No neighbouring episodes in the loaded library");return;}String[] names=new String[movies.size()];for(int i=0;i<names.length;i++)names[i]=MediaTitle.parse(movies.get(i).title).display();choose("Episodes",names,n->play(movies.get(n)));}
 void play(Movie movie){a.savePosition();a.release();a.subtitleUri=null;a.subtitleMime=null;a.appliedAutoSubtitle="";a.session.selectMovie(movie);int selected=-1;for(int i=0;i<a.items.size();i++)if(a.items.get(i).cacheIdentity().equals(movie.cacheIdentity()))selected=i;if(selected<0){a.items.add(movie);selected=a.items.size()-1;}a.index=selected;a.streamStats=a.session.stats;a.resumePosition=movie.savedPosition(a);a.resumePlaying=true;nextDismissed=false;skipSegments=Collections.emptyList();SeriesPreferences.restore(a,movie);a.restoreMovieSettings();a.autoSubtitleBeforeStart();a.start();library.remember(movie);}
 void ended(){library.remember(a.movie());if(!library.marked(a.movie(),"watched"))library.toggle(a.movie(),"watched");Movie next=TvLibrary.neighbour(a.items,a.movie(),1);if(next==null||!a.prefs.getBoolean("tvAutoplay",true))return;if(!a.foreground){play(next);return;}nextSeconds=10;nextDialog=Ui.dialog(a).setTitle("Next episode").setMessage(MediaTitle.parse(next.title).display()).setPositiveButton("Play now",(d,w)->play(next)).setNegativeButton("Cancel",(d,w)->ui.removeCallbacksAndMessages(null)).show();Runnable countdown=new Runnable(){public void run(){if(nextDialog==null||!nextDialog.isShowing())return;if(--nextSeconds<=0){nextDialog.dismiss();play(next);}else{nextDialog.setTitle("Next episode in "+nextSeconds+"s");ui.postDelayed(this,1000);}}};ui.postDelayed(countdown,1000);}
 void tick(){if(a.player==null)return;nextUpTick();if(a.controlsVisible&&a.info!=null){long speed=a.streamStats.throughputBits()/8,buffer=a.player.getTotalBufferedDuration();a.info.setText(String.format(Locale.US,"%.2f MB/s   ·   Buffer %s   ·   %s",speed/1048576.0,CinemaInfo.time(buffer),a.decoder));a.info.setVisibility(View.VISIBLE);}}
 void chapters(){toast("Reading chapter metadata…");a.session.tasks.execute(()->{try{ReadAheadStore store=a.session.store;if(store==null)throw new java.io.IOException("No stream cache");List<ChapterReader.Chapter> result=ChapterReader.read(new ChapterReader.Source(){public long size(){return store.length;}public byte[] read(long at,int length)throws java.io.IOException{byte[] bytes=new byte[length];int done=0;while(done<length){int n=store.read(at+done,bytes,done,length-done);if(n<=0)throw new java.io.EOFException();done+=n;}return bytes;}});a.ui.post(()->{if(result.isEmpty()){List<Chapter> old=chapterList();if(old.isEmpty()){toast("No chapters found in this file");return;}String[] names=new String[old.size()];for(int i=0;i<names.length;i++)names[i]=CinemaInfo.time(old.get(i).time)+" · "+old.get(i).title;choose("Chapters",names,n->a.player.seekTo(old.get(n).time));return;}String[] names=new String[result.size()];for(int i=0;i<names.length;i++)names[i]=CinemaInfo.time(result.get(i).time)+" · "+result.get(i).title;choose("Chapters",names,n->a.player.seekTo(result.get(n).time));});}catch(Exception e){a.ui.post(()->toast("Chapters unavailable · "+e.getMessage()));}});}
 static final class Chapter{long time;String title;Chapter(long t,String s){time=t;title=s;}}
 List<Chapter> chapterList(){List<Chapter> list=new ArrayList<>();for(Tracks.Group group:a.player.getCurrentTracks().getGroups())for(int i=0;i<group.length;i++){Metadata md=group.getTrackFormat(i).metadata;if(md==null)continue;for(int j=0;j<md.length();j++){Metadata.Entry entry=md.get(j);if(entry instanceof androidx.media3.extractor.metadata.id3.ChapterFrame){androidx.media3.extractor.metadata.id3.ChapterFrame c=(androidx.media3.extractor.metadata.id3.ChapterFrame)entry;list.add(new Chapter(c.startTimeMs,c.chapterId));}}}list.sort(Comparator.comparingLong(c->c.time));return list;}
 void frame(){a.player.pause();Format format=a.player.getVideoFormat();float fps=format!=null&&format.frameRate>0?format.frameRate:25;choose("Frame step · seek precision depends on format",new String[]{"Previous frame","Next frame"},n->{a.player.setSeekParameters(androidx.media3.exoplayer.SeekParameters.EXACT);a.player.seekTo(Math.max(0,a.player.getCurrentPosition()+(n==0?-1:1)*Math.round(1000/fps)));});}
 boolean key(KeyEvent e){if(!locked)return false;int code=e.getKeyCode();if(code==KeyEvent.KEYCODE_VOLUME_UP||code==KeyEvent.KEYCODE_VOLUME_DOWN||code==KeyEvent.KEYCODE_VOLUME_MUTE)return false;if(code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER){if(e.getAction()==KeyEvent.ACTION_DOWN){if(e.getRepeatCount()==0){held=SystemClock.elapsedRealtime();ui.postDelayed(unlockTask,2000);}if(SystemClock.elapsedRealtime()-held>=2000){locked=false;toast("Remote unlocked");a.showRemoteControls();}}else {held=0;ui.removeCallbacks(unlockTask);}}return true;}
 final Runnable unlockTask=this::unlock;
 void unlock(){if(locked){locked=false;toast("Remote unlocked");a.showRemoteControls();}}
 void hidden(){ui.removeCallbacksAndMessages(null);if(nextDialog!=null){nextDialog.dismiss();nextDialog=null;}if(nextUp!=null)nextUp.setVisibility(View.GONE);if(skipButton!=null)skipButton.setVisibility(View.GONE);}
 void initCards(){nextUp=Ui.button(a,"Next episode",()->{if(nextUpMovie!=null)play(nextUpMovie);});nextUp.setVisibility(View.GONE);android.widget.FrameLayout.LayoutParams np=new android.widget.FrameLayout.LayoutParams(Ui.dp(a,260),Ui.dp(a,64),android.view.Gravity.BOTTOM|android.view.Gravity.RIGHT);np.bottomMargin=Ui.dp(a,120);np.rightMargin=Ui.dp(a,16);a.root.addView(nextUp,np);nextUp.setOnLongClickListener(v->{nextDismissed=true;nextUp.setVisibility(View.GONE);return true;});skipButton=Ui.button(a,"Skip intro",()->{if(activeSkip!=null)a.player.seekTo(activeSkip.end>=0?activeSkip.end:a.player.getDuration());});skipButton.setVisibility(View.GONE);android.widget.FrameLayout.LayoutParams sp=new android.widget.FrameLayout.LayoutParams(-2,Ui.dp(a,48),android.view.Gravity.BOTTOM|android.view.Gravity.LEFT);sp.bottomMargin=Ui.dp(a,120);sp.leftMargin=Ui.dp(a,16);a.root.addView(skipButton,sp);Movie selected=a.movie();if(a.tg.ready&&selected.chatId!=0)a.session.tasks.execute(()->{try{List<SkipSegments.Segment> segments=SkipSegments.fetch(selected);a.ui.post(()->{if(a.movie().cacheIdentity().equals(selected.cacheIdentity()))skipSegments=segments;});}catch(Exception ignored){}});}
 void nextUpTick(){if(a.player==null)return;long duration=a.player.getDuration(),position=a.player.getCurrentPosition();activeSkip=SkipSegments.active(skipSegments,position,duration);skipButton.setVisibility(activeSkip!=null&&!locked?View.VISIBLE:View.GONE);if(activeSkip!=null)skipButton.setText("Skip "+activeSkip.kind);Movie next=TvLibrary.neighbour(a.items,a.movie(),1);boolean show=!nextDismissed&&!locked&&next!=null&&duration>0&&position>=duration-30000&&position<duration-1000;nextUpMovie=next;nextUp.setVisibility(show?View.VISIBLE:View.GONE);if(show)nextUp.setText("Next · "+MediaTitle.parse(next.title).display()+"\nPlay now · hold to hide");}
 void details(){String details="Video: "+a.decoder+"\nAudio: "+a.audioDecoder+"\nSpeed: "+a.player.getPlaybackParameters().speed+"×\nBuffered: "+CinemaInfo.time(a.player.getTotalBufferedDuration())+"\nCache: "+MainActivity.size(a.streamStats.cachedBytes())+"\nStalls: "+a.streamStats.stalls+"\n"+a.movie().details();Ui.message(a,"Playback details",details);}
 void toast(String text){Toast.makeText(a,text,Toast.LENGTH_SHORT).show();}
 void close(){hidden();}
}
